export interface PinAnchor { eligible_raw: string; beacon: string; registry_root: string }

/** The pin's anchor of macroblock `j` (K or K-1), or null. */
export function pinAnchor(j: number): PinAnchor | null {
  const anchors = WS_CHECKPOINT.anchors as Record<string, PinAnchor | undefined>;
  return anchors[String(j)] ?? null;
}
